using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using Bokumyaku.Presentation;
public static class InkFlushTimingCheck {
static BokumyakuGame g;static int firstFrame;static double start;static string snapshot;
public static object Run(){g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(g==null||!g.SavePath.Contains("ink-qa-"))throw new Exception("Isolated Play required");BattleTiming.Enabled=true;firstFrame=Time.frameCount;g.AbandonRun();g.TryStartRun(42);g.SetPaused(true);snapshot=JsonUtility.ToJson(g.Run.CaptureState());start=EditorApplication.timeSinceStartup;Application.runInBackground=true;EditorApplication.update+=Poll;return "Measuring 35 root strokes without simulation advancement";}
static void Poll(){if(g==null||!EditorApplication.isPlaying){EditorApplication.update-=Poll;BattleTiming.Enabled=false;return;}EditorApplication.QueuePlayerLoopUpdate();if(g.PaintedRootSlices<35&&EditorApplication.timeSinceStartup-start<15)return;EditorApplication.update-=Poll;BattleTiming.Enabled=false;var samples=BattleTiming.Capture().Where(s=>s.frame>=firstFrame).ToArray();var flush=samples.Where(s=>s.section=="InkFlush").ToArray();var roots=samples.Where(s=>s.section=="RootFlourish").ToArray();var r=new{passed=g.PaintedRootSlices==35&&snapshot==JsonUtility.ToJson(g.Run.CaptureState())&&flush.Length>0,roots=g.PaintedRootSlices,flushSamples=flush.Length,flushMaxMs=flush.Length==0?0:flush.Max(s=>s.milliseconds),rootRecordedMaxMs=roots.Length==0?0:roots.Max(s=>s.milliseconds),samples,method="Editor isolated paused seed42 initial roots. Root timing records >=10ms, flush >=0.01ms. CPU submission timings, not GPU completion or Windows stall proof."};File.WriteAllText(Path.GetFullPath("../docs/evidence/ink-flush-timing.json"),Newtonsoft.Json.JsonConvert.SerializeObject(r,Newtonsoft.Json.Formatting.Indented));}
}
